#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
int main() {
    int fd = open("my_file.txt", O_RDWR | O_CREAT, 0666);
    if (fd == -1) return 1;
    ftruncate(fd, 1024); // Ensure file is at least 1KB
    char *map = mmap(NULL, 1024, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) return 1;
    strcpy(map, "Hello, world!");
    munmap(map, 1024);
    close(fd);
    return 0;
}
